(function(){'use strict';var v='2026.08.08.1',k='chatbot_ui_policy_version';try{if(sessionStorage.getItem(k)!==v){sessionStorage.removeItem('api_engine_v4_list');sessionStorage.removeItem('api_engine_v5_list');sessionStorage.setItem(k,v)}}catch(e){}function styles(){if(document.getElementById('chatbot-ui-policy-style'))return;var s=document.createElement('style');s.id='chatbot-ui-policy-style';s.textContent='.ae-order-advanced{margin:4px 12px 8px;border-top:1px solid var(--ae-border)}.ae-order-advanced summary{padding:12px 2px 8px;color:var(--ae-text-muted);font-size:13px;font-weight:600;cursor:pointer;user-select:none}.ae-order-advanced[open] summary{color:var(--ae-accent)}.ae-order-advanced .ae-order-advanced-item{padding-left:8px;padding-right:8px}';document.head.appendChild(s)}function orderActive(){var i=document.getElementById('chat-input');return!!(i&&/#don_hang\b/i.test(String(i.value||'')))}function sync(menu){if(!menu)return;var detail=menu.querySelector('.ae-menu-item[data-code="@hoa_don_chi_tiet"]');if(detail&&detail.querySelector('.ae-menu-copy'))detail.remove();if(!orderActive())return;Array.prototype.slice.call(menu.querySelectorAll('.ae-menu-item')).forEach(function(item){var code=String(item.getAttribute('data-code')||'').toLowerCase();if(code==='@topn'||code==='@soluong')item.remove()});var customer=menu.querySelector('.ae-menu-item[data-code="@MaKhachHang"],.ae-menu-item[data-code="@makhachhang"]');if(!customer||customer.closest('.ae-order-advanced'))return;var details=document.createElement('details');details.className='ae-order-advanced';var summary=document.createElement('summary');summary.textContent='Bộ lọc thêm';customer.classList.add('ae-order-advanced-item');details.appendChild(summary);details.appendChild(customer);menu.appendChild(details);function toggle(){customer.classList.toggle('ae-menu-item',details.open)}details.addEventListener('toggle',toggle);toggle()}function start(){if(!document.body)return;styles();new MutationObserver(function(){document.querySelectorAll('.ae-menu').forEach(sync)}).observe(document.body,{childList:true,subtree:true});document.querySelectorAll('.ae-menu').forEach(sync)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start()})();
